extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var script: GDScript = load("res://core/save_manager.gd") as GDScript
	if not check("script_loaded", script != null, "Lo script res://core/save_manager.gd deve caricarsi senza errori"):
		return

	var data: Dictionary = script.call("create_save_dictionary", 1, "res://story/chapters/chapter_01.json", 2, {"key": true}, "res://assets/sprites/background.png", "res://assets/audio/music_loop.wav")
	check("version_field", data.get("version", 0) == 1, "Il dizionario deve contenere 'version' uguale a 1")
	check("story_file_field", data.get("story_file", "") == "res://story/chapters/chapter_01.json", "Il dizionario deve contenere 'story_file'")
	check("line_index_field", data.get("line_index", -1) == 2, "Il dizionario deve contenere 'line_index'")
	check("variables_field", data.get("variables", {}).get("key", false) == true, "Il dizionario deve contenere 'variables'")

	var test_path := "user://test_save_ex1.json"
	var saved: bool = script.call("save_to_file", data, test_path)
	check("save_returns_true", saved == true, "save_to_file deve restituire true quando il file viene salvato")
	check("file_created", FileAccess.file_exists(test_path), "Il file JSON deve essere creato su disco")

	var loaded: Dictionary = script.call("load_from_file", test_path)
	check("load_correct", loaded.get("version", 0) == 1, "load_from_file deve caricare i dati se la versione coincide")

	var invalid_data := data.duplicate()
	invalid_data["version"] = 99
	script.call("save_to_file", invalid_data, test_path)
	var loaded_invalid: Dictionary = script.call("load_from_file", test_path)
	check("version_mismatch", loaded_invalid.is_empty(), "load_from_file deve restituire un dizionario vuoto se la versione nel file differisce da SAVE_VERSION")

	if FileAccess.file_exists(test_path):
		DirAccess.remove_absolute(test_path)

